const icons={arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',back:'<path d="m14 6-6 6 6 6"/>',next:'<path d="m9 6 6 6-6 6"/>',book:'<path d="M3 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-3H3zm18 0h-6a3 3 0 0 0-3 3v14a4 4 0 0 1 4-3h5z"/>',leaf:'<path d="M20 3C8 2 3 7 4 14s11 10 15-1c1-3 1-6 1-10ZM4 21l11-12"/>',math:'<path d="M18 4H6l7 8-7 8h12"/>',history:'<path d="m3 8 9-5 9 5zM4 21h16M6 10v8m6-8v8m6-8v8"/>',send:'<path d="m12 19 0-14m-5 5 5-5 5 5"/>',plus:'<path d="M5 12h14M12 5v14"/>',minus:'<path d="M5 12h14"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z"/>',chat:'<path d="M20 11a8 8 0 0 1-8 8H5l-3 3V11a9 9 0 0 1 18 0Z"/>',check:'<path d="m5 12 4 4L19 6"/>'};
const icon=(name)=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.book}</svg>`;
const subjects=[{id:'biology',name:'Biology',chapter:'Cell structure & organisation',icon:'leaf',color:'#5e8e80',tint:'#eff7f3',progress:40,lessons:'2 of 5 chapters'},{id:'math',name:'Mathematics',chapter:'Quadratic functions & equations',icon:'math',color:'#557cbb',tint:'#f0f4fc',progress:25,lessons:'1 of 4 chapters'},{id:'history',name:'Sejarah',chapter:'Warisan Negara Bangsa',icon:'history',color:'#9973b5',tint:'#f6f0fa',progress:60,lessons:'3 of 5 chapters'}];
const lessons={biology:[{title:'The building blocks of life',section:'2.1 Cell structure and function',intro:'Every living organism is made up of cells. A cell is the smallest unit that can carry out the processes of life, from obtaining energy to growing and reproducing.',heading:'A small world, working together',body:'Within a cell, specialised structures called <mark>organelles</mark> perform different tasks. Each organelle has a particular function, but they work together to keep the cell alive.',rows:[['Nucleus','Contains genetic material and controls the activities of the cell.'],['Mitochondrion','The site of aerobic respiration, where energy is released to produce ATP.'],['Ribosome','Synthesises proteins needed for growth and repair.'],['Cell membrane','Controls the movement of substances into and out of the cell.']],note:'Structure supports function. When learning an organelle, connect what it looks like to the job it performs.'},{title:'Plant and animal cells',section:'2.2 Comparing cells',intro:'Plant and animal cells have much in common. Both contain a nucleus, cytoplasm, a cell membrane, mitochondria and ribosomes.',heading:'What makes a plant cell different?',body:'Plant cells also have a <mark>cell wall</mark>, chloroplasts in photosynthetic tissues, and a large central vacuole. These structures support the plant’s way of life.',rows:[['Cell wall','A rigid cellulose layer that supports the cell and maintains its shape.'],['Chloroplast','Contains chlorophyll, which absorbs light for photosynthesis.'],['Vacuole','Contains cell sap and helps maintain turgor pressure.']],note:'Animal cells do not have a cellulose cell wall or chloroplasts. Always compare the same structure in both cell types.'},{title:'From cells to organisms',section:'2.3 Cell organisation',intro:'In a multicellular organism, specialised cells work in groups. This organisation allows the organism to perform complex functions.',heading:'The levels of organisation',body:'Similar cells form tissues. Different tissues work together in organs. Organs coordinate in systems that support the whole <mark>organism</mark>.',rows:[['Cell','A muscle cell can contract.'],['Tissue','Muscle tissue is a group of muscle cells.'],['Organ','The heart contains several tissues working together.'],['System','The circulatory system transports substances around the body.']],note:'Remember the sequence: cell → tissue → organ → organ system → organism.'}],math:[{title:'Understanding quadratics',section:'1.1 Quadratic functions',intro:'A quadratic function has the form f(x) = ax² + bx + c, where a is not zero. Its graph is a curve called a parabola.',heading:'Reading the shape of the graph',body:'The sign of <mark>a</mark> determines the direction of the curve. A positive value gives a minimum point; a negative value gives a maximum point.',rows:[['a > 0','The parabola opens upwards and has a minimum.'],['a < 0','The parabola opens downwards and has a maximum.'],['c','The y-intercept of the graph is (0, c).']],note:'Start by identifying a, b and c. The coefficient of x² tells you which way the curve opens.'},{title:'Solving by factorisation',section:'1.2 Quadratic equations',intro:'A quadratic equation can sometimes be written as the product of two linear factors. If their product is zero, at least one factor must be zero.',heading:'One equation, two possible roots',body:'For <mark>x² − 5x + 6 = 0</mark>, find two numbers whose product is 6 and whose sum is −5. They are −2 and −3.',rows:[['Factorise','(x − 2)(x − 3) = 0'],['First root','x − 2 = 0, so x = 2.'],['Second root','x − 3 = 0, so x = 3.']],note:'Substitute both roots back into the original equation to check your answer.'}],history:[{title:'Warisan Negara Bangsa',section:'1.1 Latar belakang negara bangsa',intro:'Pembentukan negara bangsa di Alam Melayu mempunyai ciri tersendiri. Kerajaan, rakyat, kedaulatan dan undang-undang menjadi asas perkembangan kerajaan Melayu.',heading:'Asas sebuah kerajaan',body:'Warisan Kesultanan Melayu Melaka menunjukkan hubungan antara pemerintah dengan rakyat. <mark>Kedaulatan</mark> merujuk kepada kekuasaan tertinggi sesebuah kerajaan.',rows:[['Raja','Pemerintah yang menjadi tonggak kerajaan.'],['Rakyat','Penduduk yang memberi kesetiaan kepada pemerintah.'],['Wilayah pengaruh','Kawasan yang menerima pemerintahan seseorang raja.'],['Undang-undang','Peraturan untuk menjaga keamanan dan kesejahteraan.']],note:'Hubungkan setiap ciri negara bangsa dengan peranannya. Elakkan menghafal istilah tanpa memahami maksudnya.'},{title:'Peranan undang-undang',section:'1.2 Pentadbiran kerajaan',intro:'Undang-undang membantu kerajaan mentadbir dengan teratur dan mengekalkan keharmonian dalam masyarakat.',heading:'Peraturan untuk kesejahteraan',body:'Kesultanan Melayu Melaka mempunyai <mark>Hukum Kanun Melaka</mark> dan Undang-Undang Laut Melaka sebagai panduan pentadbiran dan kegiatan maritim.',rows:[['Hukum Kanun Melaka','Merangkumi perkara seperti pentadbiran, jenayah dan urusan masyarakat.'],['Undang-Undang Laut','Menjadi panduan tentang peranan serta tanggungjawab dalam pelayaran.']],note:'Bezakan fungsi undang-undang di darat dengan fungsi undang-undang dalam pelayaran.'}]};
let currentSubject='biology',page=0,zoom=100,mobilePane='book',quizIndex=0,score=0,answered=false;
const app=document.getElementById('app');
function home(){app.innerHTML=`<div class="wrap"><section class="greeting"><div><div class="eyebrow">YOUR STUDY SPACE</div><h1>A little progress, every day.</h1><p>Pick up where you left off. Find your flow.</p></div><span class="date">Form 4 · SPM preparation</span></section><section class="continue"><div class="continue-main"><span class="pill">CONTINUE LEARNING</span><h2>Small cells. Big discoveries.</h2><p>Biology · Chapter 2 · Cell structure & organisation</p><a class="primary" href="#study/biology">Continue studying ${icon('arrow')}</a></div><div class="continue-aside"><div class="ring"><span>4 <small>/ 5</small></span></div><div class="goal-copy"><h3>You’re building a habit.</h3><p>4 study days this week.<br>One more to reach your goal.</p></div></div></section><div class="section-head"><h2>Your subjects</h2><span>Form 4</span></div><section class="subjects">${subjects.map(s=>`<a class="subject" href="#study/${s.id}" style="--accent:${s.color};--tint:${s.tint}"><div class="subject-top"><span class="subject-icon">${icon(s.icon)}</span>${icon('arrow')}</div><h3>${s.name}</h3><p>${s.chapter}</p><div class="progress"><i style="width:${s.progress}%"></i></div><div class="subject-meta"><span>${s.lessons}</span><span>${s.progress}%</span></div></a>`).join('')}</section><div class="bottom-note"><span>Make it stick with a little practice.</span><a href="#quiz">Try a quick Biology quiz ${icon('arrow')}</a></div></div>`;}
function study(subject){currentSubject=subjects.some(s=>s.id===subject)?subject:'biology';page=0;zoom=100;const s=subjects.find(s=>s.id===currentSubject);app.innerHTML=`<div class="study-shell"><div class="study-heading"><div class="breadcrumb"><a href="#home">${icon('back')} Your subjects</a><span>/</span><strong>${s.name}</strong><span>/</span><span>${s.chapter}</span></div><span class="pill">Form 4</span></div><div class="mobile-switch"><button data-pane="book" class="${mobilePane==='book'?'active':''}">Textbook</button><button data-pane="tutor" class="${mobilePane==='tutor'?'active':''}">AI tutor</button></div><div class="workspace" data-pane="${mobilePane}"><section class="reader" aria-label="Textbook"><div class="reader-toolbar"><div class="toolgroup">${icon('book')}<span>Sample textbook</span></div><div class="toolgroup"><button class="icon-button" id="previous" aria-label="Previous page">${icon('back')}</button><span id="page-counter"></span><button class="icon-button" id="next" aria-label="Next page">${icon('next')}</button></div><div class="toolgroup"><button class="icon-button" id="zoom-out" aria-label="Zoom out">${icon('minus')}</button><span class="zoom-label" id="zoom-label">100%</span><button class="icon-button" id="zoom-in" aria-label="Zoom in">${icon('plus')}</button></div></div><div class="reader-scroll"><article class="book" id="book"></article></div></section><aside class="tutor" aria-label="AI tutor"><header class="tutor-header"><div class="tutor-title"><img src="assets/spmflow-logo.png" alt=""><div><h2>Your study companion</h2><p>Grounded in the page you’re reading</p></div></div><span>DEMO</span></header><div class="chat-scroll" id="chat" role="log" aria-live="polite"><div class="source-context">${icon('book')} ${s.name} · Form 4</div><div class="chat-intro"><h3>A little clarity.<br>A lot more confidence.</h3><p>Ask about this page, break down a tricky idea, or check what you’ve learned.</p></div><div class="suggestions"><button class="suggestion" data-prompt="Summarise this page">Summarise this page ${icon('arrow')}</button><button class="suggestion" data-prompt="Explain the key idea simply">Explain the key idea simply ${icon('arrow')}</button><button class="suggestion" data-prompt="Give me a practice question">Give me a practice question ${icon('arrow')}</button></div></div><div class="composer-area"><form id="chat-form" class="composer"><label class="sr-only" for="chat-input">Ask about this page</label><textarea id="chat-input" placeholder="Ask about this page…" maxlength="1500" rows="2"></textarea><div class="composer-controls"><span>Using the current textbook page</span><button type="submit" class="send" aria-label="Send message">${icon('send')}</button></div></form><p class="disclaimer">Interactive demo · Sample replies, not a live AI tutor.</p></div></aside></div></div>`;renderPage();document.getElementById('previous').onclick=()=>changePage(-1);document.getElementById('next').onclick=()=>changePage(1);document.getElementById('zoom-out').onclick=()=>changeZoom(-10);document.getElementById('zoom-in').onclick=()=>changeZoom(10);document.querySelectorAll('[data-pane]').forEach(b=>{if(b.tagName==='BUTTON')b.onclick=()=>{mobilePane=b.dataset.pane;document.querySelector('.workspace').dataset.pane=mobilePane;document.querySelectorAll('.mobile-switch button').forEach(x=>x.classList.toggle('active',x.dataset.pane===mobilePane));};});document.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=()=>sendMessage(b.dataset.prompt));document.getElementById('chat-form').onsubmit=e=>{e.preventDefault();sendMessage(document.getElementById('chat-input').value);};document.getElementById('chat-input').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();document.getElementById('chat-form').requestSubmit();}};}
function renderPage(){const p=lessons[currentSubject][page];document.getElementById('book').innerHTML=`<div class="book-kicker"><span>${subjects.find(s=>s.id===currentSubject).name.toUpperCase()} / FORM 4</span><span>SAMPLE LESSON</span></div><h1>${p.title}</h1><p>${p.intro}</p><h2>${p.heading}</h2><p>${p.body}</p><div class="concept-table">${p.rows.map(([term,desc])=>`<div class="concept-row"><strong>${term}</strong><span>${desc}</span></div>`).join('')}</div><div class="book-callout"><strong>Remember this</strong>${p.note}</div><div class="book-footer"><span>${p.section}</span><span>${page+1}</span></div>`;document.getElementById('page-counter').textContent=`${page+1} / ${lessons[currentSubject].length}`;document.getElementById('previous').disabled=page===0;document.getElementById('next').disabled=page===lessons[currentSubject].length-1;document.querySelector('.reader-scroll').scrollTop=0;}
function changePage(delta){page=Math.max(0,Math.min(lessons[currentSubject].length-1,page+delta));renderPage();}
function changeZoom(delta){zoom=Math.max(80,Math.min(140,zoom+delta));document.getElementById('book').style.zoom=zoom/100;document.getElementById('zoom-label').textContent=zoom+'%';document.getElementById('zoom-out').disabled=zoom===80;document.getElementById('zoom-in').disabled=zoom===140;}
function sendMessage(raw){const text=raw.trim();if(!text)return;document.getElementById('chat-input').value='';document.querySelector('.suggestions')?.remove();const chat=document.getElementById('chat'),u=document.createElement('div');u.className='message user';u.textContent=text;chat.appendChild(u);const l=lessons[currentSubject][page],q=text.toLowerCase();let reply;if(/summ|ringkas/.test(q))reply=`Here’s the page in a nutshell: ${l.intro} ${l.note}`;else if(/question|quiz|soalan|practice/.test(q))reply=currentSubject==='biology'?'Try this: Which organelle releases energy through aerobic respiration, and why might a muscle cell need many of them? Think about the energy needed for movement.':currentSubject==='math'?'Try this: For f(x) = 2x² − 5x + 3, does the graph have a maximum or a minimum? Explain how you know.':'Cuba jawab: Apakah maksud kedaulatan dan mengapakah kedaulatan penting kepada sesebuah kerajaan?';else if(/simple|simply|key idea|explain/.test(q))reply=`Let’s start with the main idea. ${l.rows[0][0]}: ${l.rows[0][1]} ${l.note}`;else{const row=l.rows.find(([term])=>q.includes(term.toLowerCase())||(term==='Mitochondrion'&&q.includes('mitochond')));reply=row?`${row[0]}: ${row[1]} ${l.note}`:'This demo has a few sample explanations for the current page. Try “Summarise this page”, “Explain the key idea simply”, or ask about one of the terms in the textbook.';}const a=document.createElement('div');a.className='message assistant';const label=document.createElement('div');label.className='assistant-label';label.innerHTML='<img src="assets/spmflow-logo.png" alt=""> spmflow · Sample reply';const body=document.createElement('div');body.textContent=reply;const cite=document.createElement('button');cite.className='citation';cite.textContent=`Sample textbook · Page ${page+1}`;const citedPage=page;cite.onclick=()=>{page=citedPage;renderPage();if(matchMedia('(max-width:720px)').matches)document.querySelector('button[data-pane="book"]').click();};a.append(label,body,cite);chat.appendChild(a);chat.scrollTop=chat.scrollHeight;}
const questions=[{q:'Which organelle releases energy through aerobic respiration?',options:['Nucleus','Mitochondrion','Ribosome','Cell membrane'],answer:1,explain:'Mitochondria are the sites of aerobic respiration, where energy is used to produce ATP.',hint:'Think about the organelle that helps power cellular activities.'},{q:'Which structure is present in plant cells but absent in animal cells?',options:['Nucleus','Cell membrane','Cell wall','Cytoplasm'],answer:2,explain:'Plant cells have a rigid cellulose cell wall. Animal cells do not.',hint:'This rigid outer layer supports the plant cell.'},{q:'Which sequence shows increasing levels of organisation?',options:['Cell → organ → tissue → system','Tissue → cell → organ → system','Cell → tissue → organ → system','System → organ → tissue → cell'],answer:2,explain:'Cells form tissues, tissues form organs, and organs work together in organ systems.',hint:'Start with the smallest living unit.'}];
function quiz(){quizIndex=0;score=0;renderQuiz();}
function renderQuiz(){answered=false;const q=questions[quizIndex];app.innerHTML=`<div class="quiz-wrap"><a class="back-link" href="#study/biology">${icon('back')} Back to textbook</a><div class="quiz-header"><span class="pill">BIOLOGY · FORM 4</span><h1>A quick check-in.</h1><p>Three questions. See what’s starting to stick.</p></div><div class="quiz-progress"><span>Question ${quizIndex+1} of ${questions.length}</span><span>Cell structure & organisation</span></div><div class="progress"><i style="width:${quizIndex/questions.length*100}%"></i></div><section class="question"><h2>${q.q}</h2><form id="quiz-form"><fieldset class="answers" style="border:0;padding:0;margin:0"><legend class="sr-only">Choose one answer</legend>${q.options.map((o,i)=>`<label class="answer"><input type="radio" name="answer" value="${i}" required><span>${o}</span></label>`).join('')}</fieldset><div id="feedback" aria-live="polite"></div><div class="quiz-actions"><button class="text-button" type="button" id="hint">Need a hint?</button><button class="primary" id="check-answer" type="submit">Check answer ${icon('arrow')}</button></div></form></section></div>`;document.getElementById('hint').onclick=()=>{const f=document.getElementById('feedback');f.className='feedback';f.textContent=q.hint;};document.getElementById('quiz-form').onsubmit=e=>{e.preventDefault();if(answered){quizIndex++;if(quizIndex===questions.length)showResults();else renderQuiz();return;}const selected=document.querySelector('input[name="answer"]:checked');if(!selected)return;const correct=Number(selected.value)===q.answer;if(correct)score++;answered=true;document.querySelectorAll('input[name="answer"]').forEach(x=>x.disabled=true);const f=document.getElementById('feedback');f.className='feedback';f.textContent=(correct?'That’s right. ':'Not quite. ')+q.explain;document.getElementById('hint').hidden=true;document.getElementById('check-answer').innerHTML=(quizIndex===2?'See results':'Next question')+' '+icon('arrow');};}
function showResults(){app.innerHTML=`<div class="quiz-wrap"><div class="question results"><div class="ring" style="background:conic-gradient(#8054e8 ${score/3*100}%,#eeeaf9 0)"><span>${score} <small>/ 3</small></span></div><div class="eyebrow">PRACTICE COMPLETE</div><h2>${score===3?'You’ve got this.':'Progress starts here.'}</h2><p>${score===3?'A strong understanding of the basics.':'Revisit the lesson, then give it another go.'}</p><div style="display:flex;gap:15px;justify-content:center;flex-wrap:wrap;margin-top:26px"><a class="primary" href="#study/biology">Back to textbook ${icon('arrow')}</a><button class="text-button" id="retry">Try again</button></div></div></div>`;document.getElementById('retry').onclick=quiz;}
function route(){const [view,subject]=location.hash.slice(1).split('/');document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===(view||'home')));if(view==='study')study(subject);else if(view==='quiz')quiz();else home();window.scrollTo(0,0);}
window.addEventListener('hashchange',route);route();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});try{Promise.resolve(document.modelContext.registerTool({name:'open_sample_textbook',description:'Open a sample subject and page in the visible textbook and tutor workspace.',inputSchema:{type:'object',properties:{subject:{type:'string',enum:['biology','math','history']},page:{type:'integer',minimum:1}},required:['subject','page'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!Object.hasOwn(lessons,input.subject)||!Number.isInteger(input.page)||input.page<1||input.page>lessons[input.subject].length)throw new Error('Choose an available subject and page.');history.replaceState(null,'','#study/'+input.subject);route();page=input.page-1;renderPage();return {subject:input.subject,page:page+1,title:lessons[currentSubject][page].title};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}}
